public void startAutoLoadPolicy(long d) {
        if (!autoLoadRunning.compareAndSet(0, 1)) {
            return;
        }

        Thread thread = new Thread(() -> {
            try {
                int n = 1;
                while (true) {
                    TimeUnit.MILLISECONDS.sleep(d);
