                    // System.out.println("Load policy for time: " + n);
                    n++;
                    if (Thread.interrupted()) {
                        break;
                    }
                }
            } catch (InterruptedException ignored) {
                // Thread interrupted, exit the loop
            } finally {
                autoLoadRunning.set(0);
            }
        });
        thread.start();
    }

