    @BeforeEach
    void setUp() {
        // Initialize a basic enforcer with a simple model and policy
        enforcer = new CachedEnforcer();

        // Add a simple model
        String modelText = "[request_definition]\n" +
                          "r = sub, obj, act\n" +
                          "\n" +
                          "[policy_definition]\n" +
                          "p = sub, obj, act\n" +
                          "\n" +
                          "[policy_effect]\n" +
                          "e = some(where (p.eft == allow))\n" +
                          "\n" +
                          "[matchers]\n" +
                          "m = r.sub == p.sub && r.obj == p.obj && r.act == p.act";
        enforcer.setModelText(modelText);

        // Add some policy rules
        enforcer.addPolicy("alice", "data1", "read");
        enforcer.addPolicy("bob", "data2", "write");
    }

    @Test
    void testEnforceWithCacheEnabled() {
        // Enable cache
        enforcer.enableCache(true);

        // First call - should compute and cache the result
        boolean result1 = enforcer.enforce("alice", "data1", "read");
        assertTrue(result1);

        // Second call - should use cached result
        boolean result2 = enforcer.enforce("alice", "data1", "read");
        assertTrue(result2);
    }

    @Test
    void testEnforceWithCacheDisabled() {
        // Disable cache
        enforcer.enableCache(false);

        // Call enforce - should bypass cache
        boolean result = enforcer.enforce("bob", "data2", "write");
        assertTrue(result);
    }

    @Test
    void testEnforceWithNullKey() {
        // Enable cache
        enforcer.enableCache(true);

        // Mock getKey to return null by passing empty args
        // This should bypass cache and call super.enforce
        boolean result = enforcer.enforce();
        assertFalse(result);
    }

    @Test
    void testEnforceCacheMiss() {
        // Enable cache
        enforcer.enableCache(true);

        // First call with new request - should compute and cache
        boolean result1 = enforcer.enforce("alice", "data2", "write");
        assertFalse(result1);

        // Second call with same request - should use cache
        boolean result2 = enforcer.enforce("alice", "data2", "write");
        assertFalse(result2);
    }

    @Test
    void testEnforceDifferentRequests() {
        // Enable cache
        enforcer.enableCache(true);

        // Call with first request
        boolean result1 = enforcer.enforce("alice", "data1", "read");
        assertTrue(result1);

        // Call with different request
        boolean result2 = enforcer.enforce("bob", "data2", "write");
        assertTrue(result2);
    }

    @Test
    void testEnforceCacheExpiration() throws InterruptedException {
        // Enable cache
        enforcer.enableCache(true);
        // Set a short expiration time for testing
        enforcer.setExpireTime(100); // 100 milliseconds

        // First call - should compute and cache
        boolean result1 = enforcer.enforce("alice", "data1", "read");
        assertTrue(result1);

        // Wait for cache to expire
        Thread.sleep(150);

        // Second call - cache should have expired, so compute again
        boolean result2 = enforcer.enforce("alice", "data1", "read");
        assertTrue(result2);
    }

    @Test
    void testEnforceWithEmptyArguments() {
        // Enable cache
        enforcer.enableCache(true);

        // Call with no arguments - should handle gracefully
        boolean result = enforcer.enforce();
        assertFalse(result);
    }

    @Test
    void testEnforceToggleCache() {
        // Start with cache disabled
        enforcer.enableCache(false);
        boolean result1 = enforcer.enforce("alice", "data1", "read");
        assertTrue(result1);

        // Enable cache
        enforcer.enableCache(true);
        boolean result2 = enforcer.enforce("alice", "data1", "read");
        assertTrue(result2);

        // Disable cache again
        enforcer.enableCache(false);
        boolean result3 = enforcer.enforce("alice", "data1", "read");
        assertTrue(result3);
    }
