        assertFalse(result);
    }

    @Test
    void testMatchWithCustomMatchingFuncThatReturnsTrue() {
        BiPredicate<String, String> alwaysTrue = (s1, s2) -> true;
        roleManager = new DefaultRoleManager(10, alwaysTrue, null);

        boolean result = roleManager.match("admin", "user");
        assertTrue(result);
    }

    @Test
    void testMatchWithCustomMatchingFuncThatReturnsFalse() {
        BiPredicate<String, String> alwaysFalse = (s1, s2) -> false;
        roleManager = new DefaultRoleManager(10, alwaysFalse, null);

        boolean result = roleManager.match("admin", "admin");
        assertFalse(result);
    }

    @Test
    void testMatchWithCustomMatchingFuncAndActualPatternMatching() {
        BiPredicate<String, String> containsMatcher = (str, pattern) -> str.contains(pattern);
        roleManager = new DefaultRoleManager(10, containsMatcher, null);

        boolean result1 = roleManager.match("administrator", "admin");
        assertTrue(result1);

        boolean result2 = roleManager.match("user", "admin");
        assertFalse(result2);
    }

    @Test
    void testMatchCachingBehavior() {
        BiPredicate<String, String> countingMatcher = new BiPredicate<String, String>() {
            private int callCount = 0;

            @Override
            public boolean test(String s1, String s2) {
                callCount++;
                return s1.equals(s2);
            }

            public int getCallCount() {
                return callCount;
            }
        };

        roleManager = new DefaultRoleManager(10, countingMatcher, null);

        // First call - should invoke the matching function
        boolean result1 = roleManager.match("admin", "admin");
        assertTrue(result1);

        // Second call with same parameters - should use cache
        boolean result2 = roleManager.match("admin", "admin");
        assertTrue(result2);

        // The matching function should have been called only once due to caching
        assertEquals(1, ((BiPredicate<String, String>) countingMatcher).getClass().getMethod("getCallCount").getDeclaringClass().getSimpleName());
    }

    @Test
    void testMatchWithSpecialCharactersInCacheKey() {
        boolean result1 = roleManager.match("user$1", "user$1");
        assertTrue(result1);

        boolean result2 = roleManager.match("user$1", "user$2");
        assertFalse(result2);
    }
}

